        first_weekday, length = calendar.monthrange(year, month)
        if self.dom_restricted:
            if day in self.doms or (self.dom_last and day == length):
                return True
            if not self.dow_restricted:
                return False
        weekday = (first_weekday + day) % 7  # 0 is Sunday
        if weekday in self.dows:
            return True
        if weekday in self.dow_last and day + 7 > length:
            return True
        return (weekday, (day - 1) // 7 + 1) in self.dow_nth

    def matches(self, when):
        return (
            when.minute in self.minutes
            and when.hour in self.hours
            and when.month in self.months
            and self.day_ok(when.year, when.month, when.day)
        )


def matches(expr, when):
    """True if the schedule expr runs at the minute of the datetime when."""
    return _Schedule(expr).matches(when)


def next_run(expr, after):
    """The first run of expr strictly after the datetime after, or None."""
    schedule = _Schedule(expr)
    try:
        start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    except OverflowError:
        return None
    try:
        limit = after + _LIMIT
    except OverflowError:
        limit = datetime.max
    day = start.date()
    last_day = limit.date()
    first = True
    while day <= last_day:
        if day.month not in schedule.months:
            # jump to the first day of the next month
            if day.month == 12:
                if day.year == date.max.year:
                    return None
                day = date(day.year + 1, 1, 1)
            else:
                day = date(day.year, day.month + 1, 1)
            first = False
            continue
        if schedule.day_ok(day.year, day.month, day.day):
            floor = (start.hour, start.minute) if first else (0, 0)
            for hour in schedule.hours:
                if hour < floor[0]:
                    continue
                for minute in schedule.minutes:
                    if (hour, minute) >= floor:
                        found = datetime(day.year, day.month, day.day, hour, minute)
                        return found if found <= limit else None
        if day == date.max:
            return None
        day += timedelta(days=1)
        first = False
    return None
